INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, language, is_classic) VALUES ('Intoy Syokoy ng Kalye Marino', 'Intoy Syokoy ng Kalye Marino', 'intoy-syokoy-ng-kalye-marino-2012', 'Intoy Syokoy ng Kalye Marino follows Intoy, a mussel caretaker in Cavite City who dreams of building a stable life with Doray, a sex worker he has loved since childhood. As both struggle with poverty and the lasting effects of the former American naval base, Intoy’s hopes for love and livelihood are threatened by an unexpected turn of nature.', '2012-01-01', 2012, 'assets/syokoy.jpg', NULL, '{"cinemalaya","indie"}', 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
